"use client";

import React, { useState } from "react";
import { PricingHeader } from "./pricing-header";
import { PricingCard } from "./pricing-card";

export interface PricingFeature {
  name: string;
}

export interface PricingTier {
  name: string;
  description: string;
  priceMonthly: string | number;
  priceAnnually: string | number;
  billedAnnuallyText?: string;
  features: PricingFeature[];
  ctaText: string;
  isPopular?: boolean;
}

const defaultTiers: PricingTier[] = [
  {
    name: "Launch",
    description: "For solo founders testing the waters and finding signal.",
    priceMonthly: 14,
    priceAnnually: 10,
    billedAnnuallyText: "Billed $120 yearly",
    features: [
      { name: "1 Active Workspace" },
      { name: "Core data reporting" },
      { name: "Standard email support" },
      { name: "Community Discord access" },
    ],
    ctaText: "Start Building",
  },
  {
    name: "Velocity",
    description: "For scaling teams that have found product-market fit.",
    priceMonthly: 59,
    priceAnnually: 47,
    billedAnnuallyText: "Billed $564 yearly",
    isPopular: true,
    features: [
      { name: "Everything in Launch" },
      { name: "Unlimited Workspaces" },
      { name: "Advanced cohort analytics" },
      { name: "Priority 1-hour response" },
      { name: "Custom domains & branding" },
      { name: "Team collaboration roles" },
    ],
    ctaText: "Start 14-Day Trial",
  },
  {
    name: "Enterprise",
    description: "For mature organizations requiring scale and compliance.",
    priceMonthly: "Custom",
    priceAnnually: "Custom",
    billedAnnuallyText: "Contact for tailored pricing",
    features: [
      { name: "Everything in Velocity" },
      { name: "Dedicated Success Manager" },
      { name: "SAML SSO & SCIM provisioning" },
      { name: "Guaranteed 99.99% SLA" },
      { name: "Audit logs & export" },
    ],
    ctaText: "Contact Sales",
  },
];

export interface PricingProps {
  /** Title of the pricing section. */
  title?: string;
  /** Subtitle of the pricing section. */
  subtitle?: string;
  /** Array of pricing tiers to display. */
  tiers?: PricingTier[];
}

export function Pricing({
  title = "Simple pricing for\nevery stage of growth.",
  subtitle = "Choose the plan that fits your team's current needs and scale effortlessly as you grow.",
  tiers = defaultTiers,
}: PricingProps) {
  const [isAnnual, setIsAnnual] = useState(true);

  return (
    <section className="relative w-full py-24 bg-white dark:bg-zinc-950 font-sans overflow-hidden">
      {/* Background Decorative Elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-[20%] left-1/2 -translate-x-1/2 w-[150%] max-w-[1200px] h-[600px] bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-blue-400/20 via-indigo-500/10 to-transparent dark:from-indigo-600/20 dark:via-purple-600/10 blur-3xl rounded-[100%] opacity-60 mix-blend-multiply dark:mix-blend-screen"></div>
        <div className="absolute top-[30%] -left-[10%] w-[400px] h-[400px] bg-rose-400/15 dark:bg-rose-500/15 rounded-full blur-[100px] mix-blend-multiply dark:mix-blend-screen animate-pulse duration-10000"></div>
        <div className="absolute bottom-[-10%] -right-[5%] w-[500px] h-[500px] bg-cyan-400/15 dark:bg-cyan-500/15 rounded-full blur-[120px] mix-blend-multiply dark:mix-blend-screen"></div>
        <div className="absolute inset-0 bg-[url('https://res.cloudinary.com/dzl9yxixg/image/upload/v1714417038/noise_oq7ym1.png')] opacity-[0.03] mix-blend-overlay"></div>
      </div>

      <div className="relative z-10 container mx-auto px-4 md:px-6 max-w-7xl">
        <PricingHeader
          title={title}
          subtitle={subtitle}
          isAnnual={isAnnual}
          setIsAnnual={setIsAnnual}
        />

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 md:gap-6 lg:gap-8 items-start">
          {tiers.map((tier) => (
            <PricingCard key={tier.name} tier={tier} isAnnual={isAnnual} />
          ))}
        </div>
      </div>
    </section>
  );
}

export default Pricing;

"use client";

import React, { useRef, useState } from "react";
import { motion, useMotionValue, useSpring, useTransform, AnimatePresence } from "motion/react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { PricingTier } from "./pricing";

interface PricingCardProps {
  tier: PricingTier;
  isAnnual: boolean;
}

export function PricingCard({ tier, isAnnual }: PricingCardProps) {
  const isPopular = tier.isPopular;
  const price = isAnnual ? tier.priceAnnually : tier.priceMonthly;
  
  // Interactive hover glow logic for subtle detailing
  const cardRef = useRef<HTMLDivElement>(null);
  const [hovered, setHovered] = useState(false);
  
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);
  const springMouseX = useSpring(mouseX, { stiffness: 150, damping: 22 });
  const springMouseY = useSpring(mouseY, { stiffness: 150, damping: 22 });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    mouseX.set(e.clientX - rect.left);
    mouseY.set(e.clientY - rect.top);
  };

  // Subtle, highly polished glow following the cursor - Rainbow colored
  const borderGradient = useTransform(
    [springMouseX, springMouseY],
    ([x, y]) => {
      return hovered
        ? `radial-gradient(250px circle at ${x}px ${y}px, rgba(255,0,0,0.1) 0%, rgba(255,165,0,0.08) 20%, rgba(255,255,0,0.06) 40%, rgba(0,255,0,0.04) 60%, rgba(0,0,255,0.02) 80%, rgba(255,255,255,0) 100%)`
        : `radial-gradient(0px circle at 0px 0px, transparent 0%, transparent 100%)`;
    }
  );

  return (
    <div
      ref={cardRef}
      className={cn(
        "relative flex flex-col h-full group transition-transform duration-500 ease-out hover:-translate-y-1 cursor-pointer",
      )}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onMouseMove={handleMouseMove}
    >
      
      {/* Subtle ambient shadow (Idle animation / Polish) - "minimum detailing" */}
      {isPopular && (
        <div className="absolute -inset-1 rounded-sm opacity-10 dark:opacity-20 blur-2xl pointer-events-none transition-all duration-700 ease-out group-hover:opacity-30 group-hover:blur-3xl"
             style={{
               background: "linear-gradient(135deg, #f87171, #fbbf24, #a3e635, #38bdf8, #818cf8, #c084fc, #f472b6)"
             }}
        />
      )}

      {/* Refined Animated Gradient Border for Popular Tier */}
      {isPopular && (
        <div className="absolute -inset-[1px] -z-10 overflow-hidden pointer-events-none rounded-none opacity-60 dark:opacity-80 transition-opacity duration-500 group-hover:opacity-100">
          {/* Base gradient - Vibrant but masked by opacity */}
          <motion.div
            className="absolute inset-[-100%] -z-10"
            style={{
              background: "conic-gradient(from 0deg at 50% 50%, #f87171, #fbbf24, #a3e635, #38bdf8, #818cf8, #c084fc, #f472b6, #f87171)",
            }}
            animate={{
              rotate: 360,
            }}
            transition={{
              repeat: Infinity,
              duration: 6,
              ease: "linear",
            }}
          />
        </div>
      )}

      {/* Mouse Tracking Inner Glow overlay (Subtle feedback) */}
      <motion.div
        className="absolute inset-0 pointer-events-none z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-500 mix-blend-overlay"
        style={{
          background: borderGradient,
        }}
      />

      <div
        className={cn(
          "relative z-10 flex flex-col h-full p-8 bg-white dark:bg-zinc-950/95 backdrop-blur-md border transition-colors duration-500 ease-out",
          isPopular 
            ? "border-transparent dark:border-transparent" 
            : "border-zinc-200 dark:border-zinc-800 group-hover:border-zinc-300 dark:group-hover:border-zinc-700 rounded-none"
        )}
      >
        {/* Corner markers for standard tiers - Moved inside z-10 container to prevent overlap crashing */}
        {!isPopular && (
          <>
            <div className="absolute -top-px -left-px w-3 h-3 border-t border-l border-zinc-400 dark:border-zinc-500 z-20" />
            <div className="absolute -top-px -right-px w-3 h-3 border-t border-r border-zinc-400 dark:border-zinc-500 z-20" />
            <div className="absolute -bottom-px -left-px w-3 h-3 border-b border-l border-zinc-400 dark:border-zinc-500 z-20" />
            <div className="absolute -bottom-px -right-px w-3 h-3 border-b border-r border-zinc-400 dark:border-zinc-500 z-20" />
          </>
        )}
        {isPopular && (
          <div className="absolute top-4 right-4 w-1.5 h-1.5 bg-indigo-500 dark:bg-indigo-400" />
        )}
        {!isPopular && (
          <div className="absolute top-4 right-4 w-1.5 h-1.5 border border-zinc-400" />
        )}

        <div className="mb-6">
          <h3 className="text-xl font-medium text-zinc-900 dark:text-white mb-2 flex items-center gap-3">
            {tier.name}
            {isPopular && (
              <span className="inline-flex items-center px-2 py-0.5 rounded-none bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-300 text-[10px] font-semibold uppercase tracking-widest border border-zinc-200 dark:border-zinc-700">
                Popular
              </span>
            )}
          </h3>
          <p className="text-sm text-zinc-500 dark:text-zinc-400 min-h-[40px]">
            {tier.description}
          </p>
        </div>

        <div className="mb-2 flex items-start">
          <span className="text-lg text-zinc-500 dark:text-zinc-400 font-medium align-top mt-1 mr-1">$</span>
          <div className="flex-1 overflow-hidden relative h-[60px]">
            <AnimatePresence mode="popLayout">
              <motion.span
                key={price}
                initial={{ y: isAnnual ? -30 : 30, opacity: 0, filter: "blur(4px)" }}
                animate={{ y: 0, opacity: 1, filter: "blur(0px)" }}
                exit={{ y: isAnnual ? 30 : -30, opacity: 0, filter: "blur(4px)" }}
                transition={{ type: "spring", bounce: 0, duration: 0.5 }}
                className="text-5xl font-medium tracking-tight text-zinc-900 dark:text-zinc-50 absolute left-0"
              >
                {price}
              </motion.span>
            </AnimatePresence>
          </div>
        </div>
        <div className="h-[20px] mb-8">
          {typeof price === "number" && (
            <span className="text-zinc-500 dark:text-zinc-400 text-sm"> / month</span>
          )}
        </div>
        
        <div className="text-[10px] font-medium tracking-widest text-zinc-500 dark:text-zinc-500 uppercase mb-8">
          {isAnnual && tier.billedAnnuallyText ? tier.billedAnnuallyText : "\u00A0"}
        </div>

        <ul className="space-y-4 mb-8 flex-1">
          {tier.features.map((feature, i) => (
            <li key={i} className="flex items-start">
              <Check className={cn(
                "h-4 w-4 mr-3 shrink-0 mt-0.5",
                isPopular ? "text-indigo-500 dark:text-indigo-400" : "text-zinc-900 dark:text-zinc-100 opacity-70"
              )} />
              <span className="text-sm text-zinc-600 dark:text-zinc-300">
                {feature.name}
              </span>
            </li>
          ))}
        </ul>

        <button
          className={cn(
            "w-full py-3.5 px-4 rounded-none text-sm font-medium transition-all duration-300 flex items-center justify-center relative overflow-hidden group/btn",
            isPopular
              ? "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-white"
              : "bg-zinc-100 text-zinc-900 hover:bg-zinc-200 dark:bg-zinc-900 dark:text-zinc-100 dark:hover:bg-zinc-800"
          )}
        >
          {isPopular && (
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-[150%] group-hover/btn:translate-x-[150%] transition-transform duration-700 ease-in-out" />
          )}
          <span className="relative z-10">{tier.ctaText}</span>
        </button>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface PricingHeaderProps {
  title: string;
  subtitle: string;
  isAnnual: boolean;
  setIsAnnual: (isAnnual: boolean) => void;
}

export function PricingHeader({ title, subtitle, isAnnual, setIsAnnual }: PricingHeaderProps) {
  return (
    <div className="flex flex-col items-center justify-center space-y-6 text-center max-w-4xl mx-auto mb-20 mt-8">
      
      <h2 className="text-4xl md:text-5xl font-semibold tracking-tight text-zinc-900 dark:text-zinc-50 whitespace-pre-line leading-tight">
        {title}
      </h2>
      
      <p className="text-zinc-500 dark:text-zinc-400 text-lg md:text-xl max-w-2xl font-normal leading-relaxed mt-4">
        {subtitle}
      </p>

      {/* Unique 3D Perspective Toggle */}
      <div 
        className="mt-10 flex items-center gap-2 p-2 relative z-20"
        style={{ perspective: "1000px" }}
      >
        {/* Monthly Button */}
        <motion.button
          onClick={() => setIsAnnual(false)}
          className={cn(
            "relative px-8 py-3.5 text-sm font-medium rounded-sm z-10 cursor-pointer overflow-hidden border",
            !isAnnual ? "border-zinc-200 dark:border-zinc-800" : "border-transparent"
          )}
          animate={{
            rotateY: isAnnual ? 15 : 0,
            rotateX: isAnnual ? 5 : 0,
            scale: isAnnual ? 0.9 : 1,
            z: isAnnual ? -20 : 0,
            opacity: isAnnual ? 0.6 : 1,
            backgroundColor: !isAnnual ? "var(--bg-active)" : "transparent",
          }}
          transition={{ type: "spring", stiffness: 300, damping: 25 }}
          style={{
            transformStyle: "preserve-3d",
            transformOrigin: "right center",
            "--bg-active": "rgba(255, 255, 255, 1)",
          } as React.CSSProperties}
        >
          {/* Active indicator inner shadow/glow */}
          {!isAnnual && (
            <motion.div 
              layoutId="glow-line"
              className="absolute bottom-0 left-0 right-0 h-0.5 bg-zinc-900 dark:bg-white"
            />
          )}
          <span className={cn(
            "relative z-10 transition-colors duration-300",
            !isAnnual ? "text-zinc-900 dark:text-zinc-900" : "text-zinc-500 dark:text-zinc-400"
          )}>
            Pay Monthly
          </span>
          {!isAnnual && (
             <div className="absolute inset-0 bg-white dark:bg-zinc-100 -z-10 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.1)]" />
          )}
        </motion.button>

        {/* Separator / Hinge */}
        <div className="w-px h-6 bg-zinc-200 dark:bg-zinc-800 rounded-full mx-1 opacity-50" />

        {/* Annually Button */}
        <motion.button
          onClick={() => setIsAnnual(true)}
          className={cn(
            "relative px-8 py-3.5 text-sm font-medium rounded-sm z-10 cursor-pointer overflow-hidden border",
            isAnnual ? "border-zinc-200 dark:border-zinc-800" : "border-transparent"
          )}
          animate={{
            rotateY: !isAnnual ? -15 : 0,
            rotateX: !isAnnual ? 5 : 0,
            scale: !isAnnual ? 0.9 : 1,
            z: !isAnnual ? -20 : 0,
            opacity: !isAnnual ? 0.6 : 1,
          }}
          transition={{ type: "spring", stiffness: 300, damping: 25 }}
          style={{
            transformStyle: "preserve-3d",
            transformOrigin: "left center",
          }}
        >
          {isAnnual && (
            <motion.div 
              layoutId="glow-line"
              className="absolute bottom-0 left-0 right-0 h-0.5 bg-zinc-900 dark:bg-white z-20"
            />
          )}
          <span className={cn(
            "relative z-10 flex items-center gap-2 transition-colors duration-300",
            isAnnual ? "text-zinc-900 dark:text-zinc-900" : "text-zinc-500 dark:text-zinc-400"
          )}>
            Pay Annually
            <span className={cn(
              "inline-flex items-center px-1.5 py-0.5 rounded-sm text-[10px] font-bold uppercase tracking-widest border",
              isAnnual 
                ? "bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-100 dark:text-emerald-700 dark:border-emerald-200" 
                : "bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-500/20 dark:text-emerald-300 dark:border-emerald-500/30"
            )}>
              Save 20%
            </span>
          </span>
          {isAnnual && (
             <div className="absolute inset-0 bg-white dark:bg-zinc-100 -z-10 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.1)]" />
          )}
        </motion.button>
      </div>
    </div>
  );
}
